import numpy as np
import time
from scipy.optimize import minimize


def _unpack(v, n):
    # v: centers (2n) then radii (n)
    xy = v[:2 * n].reshape(n, 2)
    r = v[2 * n:]
    return xy, r


def _objective(v, n):
    return -np.sum(v[2 * n:])


def _constraints(v, n):
    xy, r = _unpack(v, n)
    cons = []
    # inside square: x-r>=0, 1-x-r>=0, y-r>=0, 1-y-r>=0
    for i in range(n):
        x, y = xy[i]
        ri = r[i]
        cons.append(x - ri)        # >=0
        cons.append(1 - x - ri)
        cons.append(y - ri)
        cons.append(1 - y - ri)
    # pairwise: dist - (ri+rj) >= 0
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(xy[i, 0] - xy[j, 0], xy[i, 1] - xy[j, 1])
            cons.append(d - r[i] - r[j])
    return np.array(cons)


def _repair(xy, r, n, iters=50):
    # simple push-apart repair, then shrink to be safe
    r = np.maximum(r, 1e-6)
    for _ in range(iters):
        moved = False
        for i in range(n):
            # walls
            if xy[i, 0] - r[i] < 0:
                xy[i, 0] = r[i]; moved = True
            if xy[i, 0] + r[i] > 1:
                xy[i, 0] = 1 - r[i]; moved = True
            if xy[i, 1] - r[i] < 0:
                xy[i, 1] = r[i]; moved = True
            if xy[i, 1] + r[i] > 1:
                xy[i, 1] = 1 - r[i]; moved = True
        for i in range(n):
            for j in range(i + 1, n):
                dx = xy[j, 0] - xy[i, 0]
                dy = xy[j, 1] - xy[i, 1]
                d = np.hypot(dx, dy)
                need = r[i] + r[j]
                if d < need - 1e-12:
                    if d < 1e-12:
                        dx, dy, d = 1.0, 0.0, 1.0
                    push = (need - d) / 2 + 1e-9
                    ux, uy = dx / d, dy / d
                    xy[i, 0] -= ux * push; xy[i, 1] -= uy * push
                    xy[j, 0] += ux * push; xy[j, 1] += uy * push
                    moved = True
        if not moved:
            break
    return xy, r


