def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    deadline = budget_seconds - 0.6  # safety margin

    def elapsed():
        return time.process_time() - t0

    # ---- candidate initial configurations ----
    def hex_init():
        # Hexagonal-ish packing guess
        pts = []
        rows = 6
        for j in range(rows):
            y = (j + 0.5) / rows
            cols = 6 if j % 2 == 0 else 5
            for i in range(cols):
                x = (i + 0.5 + (0.25 if j % 2 else 0.0)) / 6
                pts.append((x, y))
        # pad
        while len(pts) < n:
            pts.append((0.5, 0.5))
        return np.array(pts[:n])

    def grid_init():
        k = 6
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:n]
        return np.array(pts)

    def from_start():
        if start is None:
            return None
        s = np.asarray(start, dtype=float)
        return s[:, :2].copy()

    starts = []
    s0 = from_start()
    if s0 is not None:
        starts.append(s0)
    starts.append(hex_init())
    starts.append(grid_init())

    best_centers = None
    best_r = None
    best_score = -1.0

    for centers in starts:
        if elapsed() > deadline * 0.5:
            break
        centers = centers.copy()
        # start radii small, grow via penalty push
        r = np.full(n, 0.01)
        centers, r, score = optimize(centers, r, n, deadline, elapsed)
        if score > best_score:
            best_score = score
            best_centers = centers.copy()
            best_r = r.copy()

    # ---- final safety shrink ----
    if best_centers is None:
        pts = grid_init()
        return np.array([[x, y, 0.02] for x, y in pts])

    centers = best_centers
    r = best_r.copy()

    # Enforce exact feasibility with iterative shrink
    for _ in range(200):
        # walls
        r = np.minimum(r, np.minimum(centers[:, 0], 1 - centers[:, 0]))
        r = np.minimum(r, np.minimum(centers[:, 1], 1 - centers[:, 1]))
        # pairs
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
                s = r[i] + r[j]
                if d < s:
                    shrink = (s - d) / 2 + 1e-12
                    r[i] = max(r[i] - shrink, 1e-9)
                    r[j] = max(r[j] - shrink, 1e-9)
                    changed = True
        if not changed:
            break

    r = np.maximum(r - 1e-9, 1e-9)
    return np.column_stack([centers, r])


def optimize(centers, r, n, deadline, elapsed):
    """Coordinate-wise penalty ascent on centers and radii."""
    centers = centers.copy()
    r = r.copy()

    def score(c, rr):
        return rr.sum()

    def total_violation(c, rr):
        v = 0.0
        x = c[:, 0]; y = c[:, 1]
        # walls
        v += np.maximum(rr - x, 0).sum()
        v += np.maximum(rr - (1 - x), 0).sum()
        v += np.maximum(rr - y, 0).sum()
        v += np.maximum(rr - (1 - y), 0).sum()
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(x[i] - x[j], y[i] - y[j])
                s = rr[i] + rr[j]
                if d < s:
                    v += (s - d)
        return v

    # initial feasible shrink
    for _ in range(50):
        x = centers[:, 0]; y = centers[:, 1]
        r = np.minimum(r, np.minimum(x, 1 - x))
        r = np.minimum(r, np.minimum(y, 1 - y))
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(x[i] - x[j], y[i] - y[j])
                s = r[i] + r[j]
                if d < s:
                    sh = (s - d) / 2
                    r[i] -= sh; r[j] -= sh
        r = np.maximum(r, 1e-9)

    step = 0.02
    best = r.sum()
    for it in range(2000):
        if elapsed() > deadline:
            break
        improved = False
        # try growing each radius
        for i in range(n):
            old = r[i]
            r[i] = old + step
            # check
            x = centers[:, 0]; y = centers[:, 1]
            ok = (r[i] <= x[i] and r[i] <= 1 - x[i] and r[i] <= y[i] and r[i] <= 1 - y[i])
            if ok:
                for j in range(n):
                    if j == i:
                        continue
                    d = np.hypot(x[i] - x[j], y[i] - y[j])
                    if d < r[i] + r[j] - 1e-12:
                        ok = False
                        break
            if ok:
                improved = True
            else:
                r[i] = old
        # try moving centers to increase slack then grow
        for i in range(n):
            xi, yi = centers[i]
            bx, by = xi, yi
            # local search direction toward open space
            bestlocal = -1
            for dx in (-step, 0, step):
                for dy in (-step, 0, step):
                    if dx == 0 and dy == 0:
                        continue
                    nx, ny = xi + dx, yi + dy
                    if nx < r[i] or nx > 1 - r[i] or ny < r[i] or ny > 1 - r[i]:
                        continue
                    ok = True
                    min_slack = 1e9
                    for j in range(n):
                        if j == i:
                            continue
                        d = np.hypot(nx - centers[j, 0], ny - centers[j, 1])
                        slack = d - (r[i] + r[j])
                        if slack < 0:
                            ok = False
                            break
                        if slack < min_slack:
                            min_slack = slack
                    if ok and min_slack > bestlocal:
                        bestlocal = min_slack
                        bx, by = nx, ny
            if bestlocal > 0:
                centers[i] = (bx, by)
                improved = True
        if improved:
            step = min(step * 1.05, 0.05)
        else:
            step *= 0.7
            if step < 1e-5:
                break

    return centers, r, r.sum()

import numpy as np
import time
from scipy.optimize import minimize


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds * 0.80
    n = 32
    rng = np.random.default_rng(20240607)

    # ---- helpers -----------------------------------------------------------
    def unpack(v):
        return v[:2 * n].reshape(n, 2), v[2 * n:]

    def pack(xy, r):
        return np.concatenate([xy.ravel(), r])

    def obj(v):
        return -np.sum(v[2 * n:])

    def cons(v):
        xy = v[:2 * n].reshape(n, 2)
        r = v[2 * n:]
        out = np.empty(4 * n + n * (n - 1) // 2)
        k = 0
        for i in range(n):
            x, y = xy[i]; ri = r[i]
            out[k] = x - ri; k += 1
            out[k] = 1 - x - ri; k += 1
            out[k] = y - ri; k += 1
            out[k] = 1 - y - ri; k += 1
        for i in range(n):
            xi, yi = xy[i]; ri = r[i]
            for j in range(i + 1, n):
                dx = xi - xy[j, 0]; dy = yi - xy[j, 1]
                out[k] = np.sqrt(dx * dx + dy * dy) - ri - r[j]; k += 1
        return out

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2 * n:] = -1.0
        return g

    def cons_jac(v):
        xy = v[:2 * n].reshape(n, 2)
        r = v[2 * n:]
        m = 4 * n + n * (n - 1) // 2
        J = np.zeros((m, 3 * n))
        k = 0
        for i in range(n):
            x, y = xy[i]; ri = r[i]
            J[k, 2 * i] = 1; J[k, 2 * n + i] = -1; k += 1
            J[k, 2 * i] = -1; J[k, 2 * n + i] = -1; k += 1
            J[k, 2 * i + 1] = 1; J[k, 2 * n + i] = -1; k += 1
            J[k, 2 * i + 1] = -1; J[k, 2 * n + i] = -1; k += 1
        for i in range(n):
            xi, yi = xy[i]; ri = r[i]
            for j in range(i + 1, n):
                dx = xi - xy[j, 0]; dy = yi - xy[j, 1]
                d = np.sqrt(dx * dx + dy * dy)
                if d < 1e-12:
                    d = 1e-12
                ux, uy = dx / d, dy / d
                J[k, 2 * i] = ux; J[k, 2 * i + 1] = uy
                J[k, 2 * j] = -ux; J[k, 2 * j + 1] = -uy
                J[k, 2 * n + i] = -1; J[k, 2 * n + j] = -1
                k += 1
        return J

    def repair(xy, r, iters=80):
        xy = xy.copy(); r = np.maximum(r.copy(), 1e-6)
        for _ in range(iters):
            moved = False
            for i in range(n):
                if xy[i, 0] - r[i] < 0:
                    xy[i, 0] = r[i]; moved = True
                if xy[i, 0] + r[i] > 1:
                    xy[i, 0] = 1 - r[i]; moved = True
                if xy[i, 1] - r[i] < 0:
                    xy[i, 1] = r[i]; moved = True
                if xy[i, 1] + r[i] > 1:
                    xy[i, 1] = 1 - r[i]; moved = True
            for i in range(n):
                for j in range(i + 1, n):
                    dx = xy[j, 0] - xy[i, 0]; dy = xy[j, 1] - xy[i, 1]
                    d = np.hypot(dx, dy)
                    need = r[i] + r[j]
                    if d < need - 1e-12:
                        if d < 1e-12:
                            dx, dy, d = 1.0, 0.0, 1.0
                        push = (need - d) / 2 + 1e-9
                        ux, uy = dx / d, dy / d
                        xy[i, 0] -= ux * push; xy[i, 1] -= uy * push
                        xy[j, 0] += ux * push; xy[j, 1] += uy * push
                        moved = True
            if not moved:
                break
        return xy, r

    def safe_final(xy, r):
        # shrink until strictly feasible with margin
        r = r.copy()
        for i in range(n):
            r[i] = min(r[i], xy[i, 0] - 1e-9, 1 - xy[i, 0] - 1e-9,
                       xy[i, 1] - 1e-9, 1 - xy[i, 1] - 1e-9)
        for _ in range(50):
            changed = False
            for i in range(n):
                for j in range(i + 1, n):
                    d = np.hypot(xy[i, 0] - xy[j, 0], xy[i, 1] - xy[j, 1])
                    if d < r[i] + r[j] + 1e-9:
                        excess = r[i] + r[j] + 1e-9 - d
                        r[i] -= excess / 2 + 1e-12
                        r[j] -= excess / 2 + 1e-12
                        changed = True
            if not changed:
                break
        r = np.maximum(r, 1e-7)
        return np.column_stack([xy, r])

    # ---- candidate seeds ---------------------------------------------------
    candidates = []
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.shape == (n, 3):
            candidates.append((s[:, :2].copy(), s[:, 2].copy()))

    # hex seeds with varying scale, plus jitter
    def hex_seed(scale, jitter):
        pts = []
        r = 0.5 * scale
        y = r
        row = 0
        while len(pts) < n and y < 1.0:
            x = r + (row % 2) * r
            while x < 1.0 - r and len(pts) < n:
                pts.append([x, y])
                x += 2 * r
            y += np.sqrt(3) * r
            row += 1
        while len(pts) < n:
            pts.append([rng.random(), rng.random()])
        xy = np.array(pts)
        if jitter > 0:
            xy += rng.normal(0, jitter, xy.shape)
            xy = np.clip(xy, 1e-3, 1 - 1e-3)
        return xy, np.full(n, 0.04)

    for sc in (0.9, 1.0, 1.1):
        for jit in (0.0, 0.01):
            candidates.append(hex_seed(sc, jit))

    # a few random seeds
    for _ in range(4):
        pts = rng.random((n, 2))
        candidates.append((pts, np.full(n, 0.03)))

    # ---- SLSQP with analytic jacobian, multi-start -------------------------
    bounds = [(0, 1)] * (2 * n) + [(1e-6, 0.5)] * n
    best_xy = None; best_r = None; best_score = -1.0

    for idx, (xy, r) in enumerate(candidates):
        if time.process_time() - t0 > deadline:
            break
        xy, r = repair(xy, r)
        v0 = pack(xy, r)
        try:
            res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                           bounds=bounds,
                           constraints={'type': 'ineq', 'fun': cons, 'jac': cons_jac},
                           options={'maxiter': 400, 'ftol': 1e-12})
            xy1, r1 = unpack(res.x)
            xy1, r1 = repair(xy1, r1)
            sc = r1.sum()
            if sc > best_score:
                best_score = sc; best_xy = xy1.copy(); best_r = r1.copy()
        except Exception:
            pass
        # early: if we have a decent result and time is short, keep going
        if time.process_time() - t0 > deadline * 0.95:
            break

    if best_xy is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        xy, r = hex_seed(1.0, 0.0)
        return safe_final(xy, r)

    # ---- local polish: re-run SLSQP from best, then repair/shrink ----------
    if time.process_time() - t0 < deadline * 0.98:
        try:
            v0 = pack(best_xy, best_r)
            res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                           bounds=bounds,
                           constraints={'type': 'ineq', 'fun': cons, 'jac': cons_jac},
                           options={'maxiter': 400, 'ftol': 1e-13})
            xy1, r1 = unpack(res.x)
            xy1, r1 = repair(xy1, r1)
            if r1.sum() > best_score:
                best_xy, best_r = xy1, r1
        except Exception:
            pass

    return safe_final(best_xy, best_r)

import numpy as np
import time
from scipy.optimize import minimize


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(987654321)
    deadline = budget_seconds * 0.85

    def elapsed():
        return time.process_time() - t0

    def unpack(v):
        return v[:2 * n].reshape(n, 2), v[2 * n:]

    def constraints(v):
        xy, r = unpack(v)
        x = xy[:, 0]; y = xy[:, 1]
        cons = np.empty(4 * n + n * (n - 1) // 2)
        cons[0:n] = x - r
        cons[n:2 * n] = 1 - x - r
        cons[2 * n:3 * n] = y - r
        cons[3 * n:4 * n] = 1 - y - r
        k = 4 * n
        idx = 0
        for i in range(n):
            dx = x[i] - x[i + 1:]
            dy = y[i] - y[i + 1:]
            d = np.sqrt(dx * dx + dy * dy)
            m = n - i - 1
            cons[k + idx:k + idx + m] = d - r[i] - r[i + 1:]
            idx += m
        return cons

    def objective(v):
        return -np.sum(v[2 * n:])

    def jac_obj(v):
        g = np.zeros_like(v)
        g[2 * n:] = -1.0
        return g

    def repair(xy, r):
        xy = xy.copy(); r = np.maximum(r.copy(), 1e-6)
        for _ in range(120):
            moved = False
            lo = r; hi = 1 - r
            for d in range(2):
                bad = xy[:, d] < lo
                if bad.any():
                    xy[bad, d] = lo[bad]; moved = True
                bad = xy[:, d] > hi
                if bad.any():
                    xy[bad, d] = hi[bad]; moved = True
            for i in range(n):
                dx = xy[i + 1:, 0] - xy[i, 0]
                dy = xy[i + 1:, 1] - xy[i, 1]
                d = np.sqrt(dx * dx + dy * dy)
                need = r[i] + r[i + 1:]
                viol = d < need - 1e-12
                if viol.any():
                    jj = np.where(viol)[0] + i + 1
                    for j in jj:
                        ddx = xy[j, 0] - xy[i, 0]
                        ddy = xy[j, 1] - xy[i, 1]
                        dd = np.hypot(ddx, ddy)
                        if dd < 1e-12:
                            ddx, ddy, dd = 1.0, 0.0, 1.0
                        push = (r[i] + r[j] - dd) / 2 + 1e-9
                        ux, uy = ddx / dd, ddy / dd
                        xy[i, 0] -= ux * push; xy[i, 1] -= uy * push
                        xy[j, 0] += ux * push; xy[j, 1] += uy * push
                        moved = True
            if not moved:
                break
        return xy, r

    bounds = [(0.0, 1.0)] * (2 * n) + [(1e-6, 0.5)] * n

    def slsqp(xy, r, maxiter, ftol):
        xy, r = repair(xy, r)
        v0 = np.concatenate([xy.ravel(), r])
        try:
            res = minimize(objective, v0, jac=jac_obj, method='SLSQP',
                           bounds=bounds,
                           constraints={'type': 'ineq', 'fun': constraints},
                           options={'maxiter': maxiter, 'ftol': ftol})
            xy1, r1 = unpack(res.x)
            xy1, r1 = repair(xy1, r1)
