import numpy as np
import time
from scipy.optimize import minimize


def _pack(v, n):
    xy = v[:2 * n].reshape(n, 2)
    r = v[2 * n:]
    return xy, r


def _cons(v, n):
    xy, r = _pack(v, n)
    out = np.empty(4 * n + n * (n - 1) // 2)
    k = 0
    for i in range(n):
        x, y = xy[i]; ri = r[i]
        out[k] = x - ri; k += 1
        out[k] = 1 - x - ri; k += 1
        out[k] = y - ri; k += 1
        out[k] = 1 - y - ri; k += 1
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(xy[i, 0] - xy[j, 0], xy[i, 1] - xy[j, 1])
            out[k] = d - r[i] - r[j]; k += 1
    return out


def _obj(v, n):
    return -np.sum(v[2 * n:])


def _jac(v, n):
    g = np.zeros_like(v)
    g[2 * n:] = -1.0
    return g


def _repair(xy, r, n, iters=200):
    xy = xy.copy(); r = np.maximum(r.copy(), 1e-6)
    for _ in range(iters):
        moved = False
        for i in range(n):
            ri = r[i]
            if xy[i, 0] < ri: xy[i, 0] = ri; moved = True
            if xy[i, 0] > 1 - ri: xy[i, 0] = 1 - ri; moved = True
            if xy[i, 1] < ri: xy[i, 1] = ri; moved = True
            if xy[i, 1] > 1 - ri: xy[i, 1] = 1 - ri; moved = True
        for i in range(n):
            for j in range(i + 1, n):
                dx = xy[j, 0] - xy[i, 0]; dy = xy[j, 1] - xy[i, 1]
                d = np.hypot(dx, dy)
                need = r[i] + r[j]
                if d < need - 1e-12:
                    if d < 1e-12:
                        dx, dy, d = 1.0, 0.0, 1.0
                    push = (need - d) / 2 + 1e-9
                    ux, uy = dx / d, dy / d
                    xy[i, 0] -= ux * push; xy[i, 1] -= uy * push
                    xy[j, 0] += ux * push; xy[j, 1] += uy * push
                    moved = True
        if not moved:
            break
    return xy, r


def _shrink_safe(xy, r, n):
    r = r.copy()
    for i in range(n):
        r[i] = min(r[i], xy[i, 0] - 1e-9, 1 - xy[i, 0] - 1e-9,
                   xy[i, 1] - 1e-9, 1 - xy[i, 1] - 1e-9)
    for _ in range(40):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(xy[i, 0] - xy[j, 0], xy[i, 1] - xy[j, 1])
                if d < r[i] + r[j] + 1e-9:
                    ex = r[i] + r[j] + 1e-9 - d
                    r[i] -= ex / 2 + 1e-10
                    r[j] -= ex / 2 + 1e-10
                    changed = True
        if not changed:
            break
    r = np.maximum(r, 1e-6)
    return r


def _solve(xy0, r0, n, maxiter):
    xy, r = _repair(xy0, r0, n)
    v0 = np.concatenate([xy.ravel(), r])
    bounds = [(0, 1)] * (2 * n) + [(1e-6, 0.5)] * n
    try:
        res = minimize(_obj, v0, args=(n,), jac=_jac, method='SLSQP',
                       bounds=bounds, constraints={'type': 'ineq', 'fun': _cons, 'args': (n,)},
                       options={'maxiter': maxiter, 'ftol': 1e-10})
        xy1, r1 = _pack(res.x, n)
        xy1, r1 = _repair(xy1, r1, n)
        return xy1, r1
    except Exception:
        return xy, r


